// === Tab: mySketch ===
const PALETTE = ["#ACDEED55", "#EAD5E855", "#84C0E755", "#38439955"];
const NOISE_SCALE = 0.01;

let particles = [];

function setup() {
	createCanvas(1112, 834);
	background("#F5F4FD");
	noStroke();
}

function draw() {
	if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
		particles.push(new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))));
	}

	for (let i = particles.length - 1; i >= 0; i--) {
		particles[i].draw();
		particles[i].update();
		if (particles[i].remove()) {
			particles.splice(i, 1);
		}
	}
}

class Particle {
	constructor(x, y) {
		this.velocity = createVector(0, 0);
		this.position = createVector(x, y);
		this.diameter = random([10, 30]);
		this.decayRate = this.diameter * random(0.002, 0.025);
		this.zOffset = random(0, 2)
		this.color = color(random(PALETTE));
	}

	update() {
		let theta = map(noise(NOISE_SCALE * this.position.x, NOISE_SCALE * this.position.y, NOISE_SCALE * this.zOffset), 0, 1, -TAU, TAU);
		this.velocity.x = cos(theta);
		this.velocity.y = sin(theta);
		this.position.add(this.velocity);
		this.diameter -= this.decayRate;
	}

	draw() {
		fill(this.color);
		circle(this.position.x, this.position.y, this.diameter);
	}

	remove() {
		return this.diameter <= 0;
	}
}

function keyPressed(){ 
  save('pix.jpg');
}

